function bounds(){const p=L.plans.get(m.root.key);return{x0:p.left-8,y0:-8,x1:p.right+8,y1:p.height+8};}
function camera(b,max=1.3){const r=$('#graph').getBoundingClientRect(),available={x:24,y:62,w:r.width-48,h:r.height-112},k=Math.min(max,available.w/(b.x1-b.x0),available.h/(b.y1-b.y0));svg.call(zoom.transform,d3.zoomIdentity.translate(available.x+available.w/2-(b.x0+b.x1)/2*k,available.y+available.h/2-(b.y0+b.y1)/2*k).scale(k));}
