function focusTopic(key=selected){const n=L.byKey.get(key);if(n?.data.type!=='topic')return;select(key);camera({x0:n.x-n.width/2-30,x1:n.x+n.width/2+30,y0:n.y-36,y1:n.y+n.height+36},16/14);$('#status').textContent='Topic Focus · full title';}
